write_file({"content":"/* 调试: 海洋/水分布 */
'use strict';
const fs = require('fs');
const path = require('path');
const vm = require('vm');
const load = (f) => vm.runInThisContext(fs.readFileSync(path.join(__dirname, '..', 'js', f), 'utf8'), { filename: f });
global.window = {};
load('constants.js'); load('noise.js'); load('worldgen.js'); load('chunks.js');

const g = new WorldGen('404');
// 网格采样高度, 统计低于海平面的比例
let below = 0, total = 0, minH = 99, minAt = null;
for (let z = -400; z <= 400; z += 16) {
  for (let x = -400; x <= 400; x += 16) {
    const h = g.heightAt(x, z);
    total++;
    if (h < SEA_LEVEL) below++;
    if (h < minH) { minH = h; minAt = [x, z]; }
  }
}
console.log(`采样${total}点, 低于海平面: ${below} (${(below / total * 100).toFixed(1)}%), 最低=${minH} @${minAt}`);
// 附近 200 范围内找水下点
let found = null;
for (let z = -200; z <= 200 && !found; z += 8) {
  for (let x = -200; x <= 200; x += 8) {
    if (g.heightAt(x, z) < SEA_LEVEL - 1) { found = [x, z, g.heightAt(x, z)]; break; }
  }
}
console.log('附近水域:', found);
","path":"tools/debug-water.js"})

