// 根据玩家眼睛位置与朝向, 计算瞄准的方块
// 相机约定(main.js): camera.rotateY(yaw + PI), camera.rotateX(-pitch)
//   => pitch>0 时朝下, yaw=0 时面朝 +Z
// 展开四元数: dir = ( sin(yaw)*cos(pitch), -sin(pitch), cos(yaw)*cos(pitch) )
function pickBlock(world, eye, yaw, pitch) {
  const dx = Math.sin(yaw) * Math.cos(pitch);
  const dy = -Math.sin(pitch);
  const dz = Math.cos(yaw) * Math.cos(pitch);
  return raycastVoxel(world, eye.x, eye.y, eye.z, dx, dy, dz, REACH);
}

