write_file({"content":"/* 调试: e2e 场景中 mouse.click 后 pitch 被重置? */
'use strict';
const { chromium } = require('playwright');
const path = require('path');

(async () => {
  const browser = await chromium.launch({ headless: true, args: ['--use-gl=angle', '--enable-webgl'] });
  const page = await browser.newPage({ viewport: { width: 1280, height: 720 } });
  page.on('pageerror', e => console.log('PAGEERROR:', e.message));
  await page.goto('file://' + path.join(__dirname, '..', 'index.html'));
  await page.waitForTimeout(500);
  await page.fill('#seed-input', '404');
  await page.click('#btn-play');
  await page.waitForTimeout(2000);

  // 复刻 e2e: 先 mouse.move 视角, 再 click 锁定, 再低头
  await page.mouse.move(640, 360);
  await page.mouse.move(900, 360);
  await page.mouse.move(700, 300);
  console.log('after moves pitch=', await page.evaluate(() => player.pitch));
  await page.mouse.click(640, 360);
  await page.waitForTimeout(300);
  console.log('locked=', await page.evaluate(() => document.pointerLockElement !== null));
  await page.evaluate(() => {
    document.dispatchEvent(new MouseEvent('mousemove', { movementX: 0, movementY: 400, bubbles: true }));
  });
  await page.waitForTimeout(50);
  const st = await page.evaluate(() => {
    const eye = { x: player.pos.x, y: player.pos.y + 1.62, z: player.pos.z };
    const dir = new THREE.Vector3(0, 0, -1).applyQuaternion(camera.quaternion);
    const hit = raycastVoxel(world, eye.x, eye.y, eye.z, dir.x, dir.y, dir.z, 5);
    return { pitch: player.pitch.toFixed(3), dir: [dir.x.toFixed(2), dir.y.toFixed(2), dir.z.toFixed(2)], hit, pos: { ...player.pos } };
  });
  console.log(JSON.stringify(st, null, 2));
  await browser.close();
})();
