'use strict';
const { chromium } = require('playwright');
const path = require('path');

(async () => {
  const browser = await chromium.launch({ headless: true, args: ['--use-gl=angle', '--enable-webgl'] });
  const page = await browser.newPage({ viewport: { width: 1280, height: 720 } });
  page.on('pageerror', e => console.log('PAGEERROR:', e.message));
  await page.goto('file://' + path.join(__dirname, '..', 'index.html'));
  await page.waitForTimeout(500);
  await page.fill('#seed-input', '404');
  await page.click('#btn-play');
  await page.waitForTimeout(2000);

  // === 完整复刻 e2e 顺序 ===
  await page.mouse.move(640, 360);
  await page.mouse.down('left');
  await page.waitForTimeout(100);
  await page.mouse.up('left');
  await page.keyboard.down('KeyW');
  await page.waitForTimeout(1000);
  await page.keyboard.up('KeyW');
  await page.keyboard.down('Space');
  await page.waitForTimeout(150);
  await page.keyboard.up('Space');
  await page.waitForTimeout(250);
  await page.mouse.click(640, 360);
  await page.waitForTimeout(300);
  await page.evaluate(() => { player.pitch = 0.9; player.yaw = 0; player.vel = { x: 0, y: 0, z: 0 }; });
  await page.waitForTimeout(250);
  await page.evaluate(async () => {
    startBreak();
    for (let i = 0; i < 100 && breakState; i++) { updateBreak(1 / 30); await new Promise(r => setTimeout(r, 5)); }
  });

  const probe = await page.evaluate(async () => {
    const log = { pos: { ...player.pos } };
    // 玩家周围 3x3 地表
    const px = Math.floor(player.pos.x), pz = Math.floor(player.pos.z);
    const map = [];
    for (let dz = -1; dz <= 1; dz++) {
      let row = '';
      for (let dx = -1; dx <= 1; dx++) {
        let gy = -1;
        for (let y = CHUNK_HEIGHT - 1; y > 0; y--) { if (world.getBlock(px + dx, y, pz + dz) !== B.AIR) { gy = y; break; } }
        row += gy + ' ';
      }
      map.push(row);
    }
    log.surfAround = map;
    // 俯视命中
    player.pitch = 0.9; player.yaw = 0; player.vel = { x: 0, y: 0, z: 0 };
    for (let i = 0; i < 6; i++) await new Promise(r => requestAnimationFrame(r));
    log.hit = currentHit ? { ...currentHit } : null;
    log.target = currentHit ? { tx: currentHit.x + currentHit.nx, ty: currentHit.y + currentHit.ny, tz: currentHit.z + currentHit.nz } : null;
    if (log.target) log.targetCur = world.getBlock(log.target.tx, log.target.ty, log.target.tz);
    return log;
  });
  console.log(JSON.stringify(probe, null, 2));
  await browser.close();
})();
