{"content":"/* WovraCraft 全局样式 */
* { margin: 0; padding: 0; box-sizing: border-box; }

html, body { width: 100%; height: 100%; overflow: hidden; background: #000; }

body {
  font-family: 'Segoe UI', 'Microsoft YaHei', sans-serif;
  user-select: none;
  -webkit-user-select: none;
}

#app { position: relative; width: 100vw; height: 100vh; }

#game-canvas { display: block; width: 100%; height: 100%; cursor: crosshair; }

.hidden { display: none !important; }

/* ---------- HUD ---------- */
#hud { position: absolute; inset: 0; pointer-events: none; }

#crosshair {
  position: absolute; left: 50%; top: 50%;
  transform: translate(-50%, -50%);
  font-size: 22px; color: rgba(255,255,255,0.85);
  text-shadow: 0 0 3px rgba(0,0,0,0.8);
  font-family: monospace;
}

#hotbar {
  position: absolute; bottom: 12px; left: 50%;
  transform: translateX(-50%);
  display: flex; gap: 4px;
  background: rgba(0,0,0,0.45);
  padding: 5px; border-radius: 6px;
  border: 2px solid rgba(0,0,0,0.5);
}

.hotbar-slot {
  width: 52px; height: 52px;
  background: rgba(255,255,255,0.12);
  border: 2px solid rgba(255,255,255,0.25);
  border-radius: 4px;
  position: relative;
  display: flex; align-items: center; justify-content: center;
}

.hotbar-slot.selected {
  border-color: #fff;
  box-shadow: 0 0 8px rgba(255,255,255,0.6);
  transform: scale(1.08);
}

.hotbar-slot .slot-icon {
  width: 34px; height: 34px;
  border-radius: 4px;
  box-shadow: inset 2px 2px 0 rgba(255,255,255,0.35),
              inset -2px -3px 0 rgba(0,0,0,0.35);
}

.hotbar-slot .slot-num {
  position: absolute; top: 1px; left: 4px;
  font-size: 10px; color: rgba(255,255,255,0.6);
  font-family: monospace;
}

.hotbar-slot .slot-name {
  position: absolute; bottom: -18px; left: 50%;
  transform: translateX(-50%);
  font-size: 11px; color: #fff;
  text-shadow: 0 1px 2px #000;
  white-space: nowrap;
  opacity: 0; transition: opacity 0.3s;
}

.hotbar-slot.selected .slot-name { opacity: 1; }

#debug {
  position: absolute; top: 8px; left: 8px;
  font-family: Consolas, monospace;
  font-size: 12px; line-height: 1.5;
  color: #fff; text-shadow: 1px 1px 0 #000;
  background: rgba(0,0,0,0.35);
  padding: 6px 10px; border-radius: 4px;
  white-space: pre;
}

#toast {
  position: absolute; top: 18%; left: 50%;
  transform: translateX(-50%);
  color: #fff; font-size: 15px;
  text-shadow: 0 1px 3px #000;
  background: rgba(0,0,0,0.5);
  padding: 8px 18px; border-radius: 20px;
  opacity: 0; transition: opacity 0.4s;
}
#toast.show { opacity: 1; }

/* 破坏进度条 */
#break-progress {
  position: absolute; left: 50%; bottom: 84px;
  transform: translateX(-50%);
  width: 120px; height: 8px;
  background: rgba(0,0,0,0.5);
  border-radius: 4px; overflow: hidden;
  opacity: 0; transition: opacity 0.15s;
}
#break-progress.active { opacity: 1; }
#break-bar {
  height: 100%; width: 0%;
  background: linear-gradient(90deg, #7ec850, #4caf50);
}

/* ---------- 菜单 ---------- */
#menu, #pause-menu {
  position: absolute; inset: 0;
  display: flex; flex-direction: column;
  align-items: center; justify-content: center;
  background: linear-gradient(180deg, rgba(10,15,35,0.92), rgba(20,40,20,0.92));
  z-index: 20;
}

#menu h1 {
  font-size: 64px; letter-spacing: 6px; color: #fff;
  text-shadow: 3px 3px 0 #3a3a3a, 0 0 24px rgba(120,200,255,0.4);
  font-weight: 900;
}
#menu h1 span { color: #7ec850; }

.subtitle { color: #cfcfcf; margin: 8px 0 28px; font-size: 15px; letter-spacing: 2px; }

.menu-panel {
  background: rgba(0,0,0,0.45);
  padding: 26px 34px; border-radius: 10px;
  border: 1px solid rgba(255,255,255,0.15);
  display: flex; flex-direction: column; gap: 14px;
  width: 400px; align-items: stretch;
}

.menu-panel label { color: #aaa; font-size: 13px; }

#seed-input {
  padding: 10px 12px; border-radius: 6px;
  border: 1px solid rgba(255,255,255,0.25);
  background: rgba(255,255,255,0.08);
  color: #fff; font-size: 15px; outline: none;
}
#seed-input:focus { border-color: #7ec850; }

.btn {
  padding: 12px; border-radius: 6px; border: none;
  font-size: 16px; font-weight: 600; cursor: pointer;
  background: rgba(255,255,255,0.12); color: #fff;
  transition: background 0.15s, transform 0.1s;
}
.btn:hover { background: rgba(255,255,255,0.22); }
.btn:active { transform: scale(0.98); }
.btn.primary { background: #4c9a3f; }
.btn.primary:hover { background: #5cb04d; }

.controls-hint {
  color: #999; font-size: 12px; line-height: 1.9;
  text-align: center; margin-top: 6px;
}
.controls-hint b { color: #ddd; background: rgba(255,255,255,0.1);
  padding: 1px 6px; border-radius: 3px; font-family: monospace; }

.menu-footer { color: #666; font-size: 12px; margin-top: 24px; }

/* 暂停菜单 */
#pause-menu { background: rgba(0,0,0,0.6); backdrop-filter: blur(4px); }
#pause-menu h2 { color: #fff; font-size: 34px; margin-bottom: 26px; }
#pause-menu .btn { width: 260px; margin-bottom: 12px; }
