{"content":"/* ============================================
 * noise.js — 带种子的柏林噪声 (Perlin) + 工具
 * 纯 JS 实现, 支持 2D/3D, 输出约 [-1,1]
 * ============================================ */
'use strict';

// mulberry32 种子随机数生成器
function mulberry32(seed) {
  let a = seed >>> 0;
  return function () {
    a |= 0; a = (a + 0x6D2B79F5) | 0;
    let t = Math.imul(a ^ (a >>> 15), 1 | a);
    t = (t + Math.imul(t ^ (t >>> 7), 61 | t)) ^ t;
    return ((t ^ (t >>> 14)) >>> 0) / 4294967296;
  };
}

// 字符串转种子 hash
function hashSeed(str) {
  let h = 1779033703 ^ str.length;
  for (let i = 0; i < str.length; i++) {
    h = Math.imul(h ^ str.charCodeAt(i), 3432918353);
    h = (h << 13) | (h >>> 19);
  }
  return (h ^ (h >>> 16)) >>> 0;
}

class Perlin {
  constructor(seed) {
    const rand = mulberry32(seed);
    // 0-255 洗牌
    this.p = new Uint8Array(512);
    const perm = new Uint8Array(256);
    for (let i = 0; i < 256; i++) perm[i] = i;
    for (let i = 255; i > 0; i--) {
      const j = Math.floor(rand() * (i + 1));
      const t = perm[i]; perm[i] = perm[j]; perm[j] = t;
    }
    for (let i = 0; i < 512; i++) this.p[i] = perm[i & 255];
  }

  static fade(t) { return t * t * t * (t * (t * 6 - 15) + 10); }
  static lerp(a, b, t) { return a + t * (b - a); }

  static grad2(hash, x, y) {
    switch (hash & 7) {
      case 0: return  x + y;
      case 1: return -x + y;
      case 2: return  x - y;
      case 3: return -x - y;
      case 4: return  x;
      case 5: return -x;
      case 6: return  y;
      default: return -y;
    }
  }

  static grad3(hash, x, y, z) {
    const h = hash & 15;
    const u = h < 8 ? x : y;
    const v = h < 4 ? y : (h === 12 || h === 14 ? x : z);
    return ((h & 1) === 0 ? u : -u) + ((h & 2) === 0 ? v : -v);
  }

  // 2D 噪声, 约 [-1,1]
  noise2(x, y) {
    const X = Math.floor(x) & 255, Y = Math.floor(y) & 255;
    x -= Math.floor(x); y -= Math.floor(y);
    const u = Perlin.fade(x), v = Perlin.fade(y);
    const p = this.p;
    const A = p[X] + Y, B = p[X + 1] + Y;
    return Perlin.lerp(
      Perlin.lerp(Perlin.grad2(p[A], x, y),     Perlin.grad2(p[B], x - 1, y), u),
      Perlin.lerp(Perlin.grad2(p[A + 1], x, y - 1), Perlin.grad2(p[B + 1], x - 1, y - 1), u),
      v
    );
  }

  // 3D 噪声, 约 [-1,1]
  noise3(x, y, z) {
    const X = Math.floor(x) & 255, Y = Math.floor(y) & 255, Z = Math.floor(z) & 255;
    x -= Math.floor(x); y -= Math.floor(y); z -= Math.floor(z);
    const u = Perlin.fade(x), v = Perlin.fade(y), w = Perlin.fade(z);
    const p = this.p;
    const A = p[X] + Y, AA = p[A] + Z, AB = p[A + 1] + Z;
    const Bq = p[X + 1] + Y, BA = p[Bq] + Z, BB = p[Bq + 1] + Z;
    return Perlin.lerp(
      Perlin.lerp(
        Perlin.lerp(Perlin.grad3(p[AA], x, y, z),     Perlin.grad3(p[BA], x - 1, y, z), u),
        Perlin.lerp(Perlin.grad3(p[AB], x, y - 1, z), Perlin.grad3(p[BB], x - 1, y - 1, z), u), v),
      Perlin.lerp(
        Perlin.lerp(Perlin.grad3(p[AA + 1], x, y, z - 1),     Perlin.grad3(p[BA + 1], x - 1, y, z - 1), u),
        Perlin.lerp(Perlin.grad3(p[AB + 1], x, y - 1, z - 1), Perlin.grad3(p[BB + 1], x - 1, y - 1, z - 1), u), v),
      w
    );
  }

  // 分形布朗运动 (2D): 多倍频叠加
  fbm2(x, y, octaves = 4, lacunarity = 2.0, gain = 0.5) {
    let amp = 1, freq = 1, sum = 0, norm = 0;
    for (let i = 0; i < octaves; i++) {
      sum += amp * this.noise2(x * freq, y * freq);
      norm += amp;
      amp *= gain; freq *= lacunarity;
    }
    return sum / norm;
  }

  // 3D fBm
  fbm3(x, y, z, octaves = 3, lacunarity = 2.0, gain = 0.5) {
    let amp = 1, freq = 1, sum = 0, norm = 0;
    for (let i = 0; i < octaves; i++) {
      sum += amp * this.noise3(x * freq, y * freq, z * freq);
      norm += amp;
      amp *= gain; freq *= lacunarity;
    }
    return sum / norm;
  }
}
