{"content":"/* ============================================
 * worldgen.js — 世界生成: 地形/生物群系/洞穴/矿石/树木
 * 确定性: 相同种子 + 相同坐标 => 相同结果
 * ============================================ */
'use strict';

class WorldGen {
  constructor(seedStr) {
    this.seedStr = String(seedStr);
    const seed = hashSeed(this.seedStr);
    this.seed = seed;
    this.nTerrain = new Perlin(seed ^ 0x1000);
    this.nHills   = new Perlin(seed ^ 0x2000);
    this.nMount   = new Perlin(seed ^ 0x3000);
    this.nTemp    = new Perlin(seed ^ 0x4000);   // 温度(生物群系)
    this.nHumid   = new Perlin(seed ^ 0x5000);   // 湿度
    this.nCave    = new Perlin(seed ^ 0x6000);   // 洞穴
    this.nCave2   = new Perlin(seed ^ 0x7000);
    this.nOre     = new Perlin(seed ^ 0x8000);
    this.nTree    = new Perlin(seed ^ 0x9000);   // 树分布
    this.nBeach   = new Perlin(seed ^ 0xA000);
  }

  // ---- 生物群系判定: 返回 0平原 1沙漠 2雪原 3山地 ----
  biomeAt(x, z) {
    const t = this.nTemp.fbm2(x * 0.004, z * 0.004, 2);
    const h = this.nHumid.fbm2(x * 0.004 + 100, z * 0.004 - 100, 2);
    const m = this.nMount.fbm2(x * 0.0015, z * 0.0015, 2);
    if (m > 0.28) return 3;              // 山地
    if (t < -0.25) return 2;             // 雪原
    if (t > 0.28 && h < 0.05) return 1;  // 沙漠
    return 0;                            // 平原
  }

  // ---- 地形高度 ----
  heightAt(x, z) {
    const base = this.nTerrain.fbm2(x * 0.008, z * 0.008, 4);       // 起伏
    const hills = this.nHills.fbm2(x * 0.02, z * 0.02, 3);          // 小丘
    const mount = this.nMount.fbm2(x * 0.004 + 500, z * 0.004, 3);  // 山脉

    let h = SEA_LEVEL + 2 + base * 10 + hills * 3;

    // 山脉隆起
    if (mount > 0.15) {
      const t = Math.min(1, (mount - 0.15) / 0.4);
      h += t * t * 26;
    }
    // 海洋压低
    const ocean = this.nTerrain.fbm2(x * 0.003 - 800, z * 0.003 + 800, 2);
    if (ocean < -0.18) {
      const t = Math.min(1, (-0.18 - ocean) / 0.25);
      h -= t * 14;
    }
    return Math.max(3, Math.min(CHUNK_HEIGHT - 6, Math.round(h)));
  }

  // ---- 洞穴: 两条 3D 噪声脊线交叉形成隧道 (简化 worms) ----
  isCave(x, y, z, surface) {
    if (y < 4 || y > surface - 3) return false;
    const s = 0.055;
    const a = this.nCave.fbm3(x * s, y * s * 1.6, z * s, 2);
    const b = this.nCave2.fbm3(x * s + 300, y * s * 1.6, z * s - 300, 2);
    // 脊线交叉: |a|<eps 且 |b|<eps => 洞
    return (a * a + b * b) < 0.008;
  }

  // ---- 矿石分布 ----
  oreAt(x, y, z) {
    const n = this.nOre.noise3(x * 0.11, y * 0.11, z * 0.11);
    if (y < 14 && n > 0.62) return B.DIAMOND_ORE;
    if (y < 24 && n > 0.56) return B.GOLD_ORE;
    if (y < 40 && n > 0.48) return B.IRON_ORE;
    if (n > 0.40) return B.COAL_ORE;
    return B.STONE;
  }

  // ---- 树判断(确定性): 世界坐标哈希 + 噪声密度 ----
  treeAt(x, z) {
    const density = this.nTree.fbm2(x * 0.01, z * 0.01, 2);
    if (density < 0.05) return 0;
    // 网格内伪随机取点, 避免树重叠
    const gx = Math.floor(x / 5), gz = Math.floor(z / 5);
    const r = mulberry32((this.seed ^ (gx * 73856093) ^ (gz * 19349663)) >>> 0)();
    const lx = ((gx * 5) + Math.floor(r * 5));
    const lz = ((gz * 5) + Math.floor(mulberry32((this.seed ^ (gx * 83492791) ^ (gz * 2971215073 % 4294967296)) >>> 0)() * 5));
    if (lx !== x || lz !== z) return 0;
    // 稀有度
    const r2 = mulberry32((this.seed ^ (x * 2654435761 % 4294967296) ^ (z * 40503)) >>> 0)();
    if (r2 > 0.35) return 0;
    return 1; // 橡树
  }

  // 生成一列方块 (x,z 世界坐标, 高度 h, 生物群系 biome)
  // 返回: { blocks: Uint8Array(CHUNK_HEIGHT), tree: 0|1 }
  column(x, z, h, biome) {
    const col = new Uint8Array(CHUNK_HEIGHT);
    for (let y = 0; y < CHUNK_HEIGHT; y++) {
      let b = B.AIR;
      if (y === 0) {
        b = B.BEDROCK;
      } else if (y < h - 3) {
        // 地下
        b = this.oreAt(x, y, z);
        if (y < 5 && mulberry32((this.seed ^ (x * 31 + z * 17 + y * 7)) >>> 0)() < 0.3) b = B.GRAVEL;
      } else if (y < h) {
        // 表层下 3 格
        b = biome === 1 ? B.SAND : B.DIRT;
      } else if (y === h) {
        // 地表
        if (biome === 1) b = B.SAND;
        else if (biome === 2) b = B.SNOW;
        else if (biome === 3) b = (h > SEA_LEVEL + 20) ? B.SNOW : B.GRASS;
        else b = (h <= SEA_LEVEL + 1) ? B.SAND : B.GRASS; // 海滩
      } else if (y <= SEA_LEVEL) {
        b = B.WATER; // 海/湖
      }
      // 洞穴(在 solid 处挖空)
      if (b !== B.AIR && b !== B.WATER && b !== B.BEDROCK && this.isCave(x, y, z, h)) {
        b = (y <= 10) ? B.AIR : B.AIR;
      }
      col[y] = b;
    }
    // 沙漠仙人掌
    if (biome === 1 && col[h] === B.SAND && h > SEA_LEVEL) {
      const r = mulberry32((this.seed ^ (x * 91 + z * 57)) >>> 0)();
      if (r < 0.006) {
        const ch = 2 + Math.floor(r * 500) % 2;
        for (let i = 1; i <= ch && h + i < CHUNK_HEIGHT; i++) col[h + i] = B.CACTUS;
      }
    }
    return col;
  }
}
