{"content":"/* ============================================
 * main.js — 游戏装配与主循环
 * 场景/相机/光照/天空/区块流送/输入/交互/昼夜/存档
 * ============================================ */
'use strict';

// ================= 全局状态 =================
const canvas = document.getElementById('game-canvas');
let renderer, scene, camera;
let world, player, inventory, particles;
let highlightMesh = null;
let gameStarted = false, paused = false;
let dayTime = DAY_LENGTH * 0.25;   // 从清晨开始
let sunLight, moonLight, ambient, hemiLight;
let skyDome = null, sunSprite = null, moonSprite = null, stars = null;
let clouds = null;
let breakState = null;   // {x,y,z,progress, id}
let currentHit = null;
let firstPerson = true;
let stats = { fps: 0, frames: 0, ft: 0 };

const keys = {};
const input = { forward: false, back: false, left: false, right: false, jump: false, sprint: false, sneak: false };

// ================= 场景初始化 =================
function initRenderer() {
  renderer = new THREE.WebGLRenderer({ canvas, antialias: true });
  renderer.setPixelRatio(Math.min(window.devicePixelRatio, 2));
  renderer.setSize(window.innerWidth, window.innerHeight);
  scene = new THREE.Scene();
  scene.fog = new THREE.Fog(0x9fc7ff, RENDER_DIST * CHUNK_SIZE * 0.55, RENDER_DIST * CHUNK_SIZE * 0.95);
  camera = new THREE.PerspectiveCamera(75, window.innerWidth / window.innerHeight, 0.1, 600);

  // 光照
  hemiLight = new THREE.HemisphereLight(0xbfd8ff, 0x8a7a5a, 0.55);
  scene.add(hemiLight);
  ambient = new THREE.AmbientLight(0xffffff, 0.35);
  scene.add(ambient);
  sunLight = new THREE.DirectionalLight(0xfff3d0, 1.0);
  sunLight.position.set(50, 100, 30);
  scene.add(sunLight);
  moonLight = new THREE.DirectionalLight(0x8899ff, 0.15);
  moonLight.position.set(-50, 100, -30);
  scene.add(moonLight);

  buildSky();
  buildClouds();

  // 选中方块高亮框
  const hlGeo = new THREE.BoxGeometry(1.002, 1.002, 1.002);
  const hlEdges = new THREE.EdgesGeometry(hlGeo);
  highlightMesh = new THREE.LineSegments(hlEdges, new THREE.LineBasicMaterial({ color: 0x111111, transparent: true, opacity: 0.7 }));
  highlightMesh.visible = false;
  scene.add(highlightMesh);

  window.addEventListener('resize', () => {
    camera.aspect = window.innerWidth / window.innerHeight;
    camera.updateProjectionMatrix();
    renderer.setSize(window.innerWidth, window.innerHeight);
  });
}

// ---- 天空: 渐变穹顶 + 太阳/月亮 + 星星 ----
function buildSky() {
  const skyGeo = new THREE.SphereGeometry(480, 24, 16);
  const skyMat = new THREE.ShaderMaterial({
    side: THREE.BackSide,
    depthWrite: false,
    uniforms: {
      topColor: { value: new THREE.Color(0x2a62c8) },
      midColor: { value: new THREE.Color(0x9fc7ff) },
      botColor: { value: new THREE.Color(0xd8e8ff) },
    },
    vertexShader: `
      varying vec3 vP;
      void main(){ vP = position; gl_Position = projectionMatrix * modelViewMatrix * vec4(position,1.0); }`,
    fragmentShader: `
      varying vec3 vP;
      uniform vec3 topColor; uniform vec3 midColor; uniform vec3 botColor;
      void main(){
        float h = normalize(vP).y;
        vec3 c = h > 0.12 ? mix(midColor, topColor, clamp((h-0.12)/0.55,0.,1.))
                          : mix(botColor, midColor, clamp((h+0.25)/0.37,0.,1.));
        gl_FragColor = vec4(c, 1.0);
      }`,
  });
  skyDome = new THREE.Mesh(skyGeo, skyMat);
  scene.add(skyDome);

  // 太阳/月亮 (发光方块片)
  const sunMat = new THREE.MeshBasicMaterial({ color: 0xffdf6b, fog: false });
  sunSprite = new THREE.Mesh(new THREE.PlaneGeometry(30, 30), sunMat);
  scene.add(sunSprite);
  const moonMat = new THREE.MeshBasicMaterial({ color: 0xdfe8ff, fog: false });
  moonSprite = new THREE.Mesh(new THREE.PlaneGeometry(22, 22), moonMat);
  scene.add(moonSprite);

  // 星星
  const starGeo = new THREE.BufferGeometry();
  const starPos = [];
  for (let i = 0; i < 400; i++) {
    const th = Math.random() * Math.PI * 2, ph = Math.acos(2 * Math.random() - 1);
    const r = 450;
    starPos.push(r * Math.sin(ph) * Math.cos(th), Math.abs(r * Math.cos(ph)), r * Math.sin(ph) * Math.sin(th));
  }
  starGeo.setAttribute('position', new THREE.Float32BufferAttribute(starPos, 3));
  stars = new THREE.Points(starGeo, new THREE.PointsMaterial({ color: 0xffffff, size: 1.6, sizeAttenuation: false, transparent: true, opacity: 0, fog: false }));
  scene.add(stars);
}

// ---- 简单平面云 ----
function buildClouds() {
  const cloudGeo = new THREE.PlaneGeometry(1400, 1400);
  const cv = document.createElement('canvas');
  cv.width = cv.height = 256;
  const cctx = cv.getContext('2d');
  cctx.clearRect(0, 0, 256, 256);
  const pn = new Perlin(12345);
  for (let y = 0; y < 64; y++) {
    for (let x = 0; x < 64; x++) {
      if (pn.fbm2(x * 0.12, y * 0.12, 3) > 0.18) {
        cctx.fillStyle = 'rgba(255,255,255,0.85)';
        cctx.fillRect(x * 4, y * 4, 4, 4);
      }
    }
  }
  const tex = new THREE.CanvasTexture(cv);
  tex.wrapS = tex.wrapT = THREE.RepeatWrapping;
  tex.repeat.set(3, 3);
  const cloudMat = new THREE.MeshBasicMaterial({ map: tex, transparent: true, opacity: 0.75, depthWrite: false, fog: false });
  clouds = new THREE.Mesh(cloudGeo, cloudMat);
  clouds.rotation.x = -Math.PI / 2;
  clouds.position.y = 90;
  scene.add(clouds);
}

// ================= 区块流送 =================
function updateChunks() {
  const pcx = Math.floor(player.pos.x / CHUNK_SIZE);
  const pcz = Math.floor(player.pos.z / CHUNK_SIZE);

  // 收集需要的区块, 按距离排序
  const need = [];
  for (let dz = -RENDER_DIST; dz <= RENDER_DIST; dz++) {
    for (let dx = -RENDER_DIST; dx <= RENDER_DIST; dx++) {
      if (dx * dx + dz * dz > (RENDER_DIST + 0.5) ** 2) continue;
      need.push([pcx + dx, pcz + dz, dx * dx + dz * dz]);
    }
  }
  need.sort((a, b) => a[2] - b[2]);

  const budget = 2; // 每帧最多生成/网格化 2 个区块(60fps 保流畅)
  let used = 0;
  for (const [cx, cz] of need) {
    const c = world.getChunk(cx, cz);
    if (!c || !c.generated || c.dirty) {
      if (used >= budget) break;
      const chunk = world.ensureChunk(cx, cz);
      rebuildChunkMesh(chunk);
      used++;
    }
  }
  // 卸载远处
  world.unloadFar(pcx, pcz);
}

function rebuildChunkMesh(chunk) {
  const data = meshChunk(world, chunk);
  // 旧网格清理
  if (chunk.mesh) { scene.remove(chunk.mesh); chunk.mesh.geometry.dispose(); chunk.mesh = null; }
  if (chunk.waterMesh) { scene.remove(chunk.waterMesh); chunk.waterMesh.geometry.dispose(); chunk.waterMesh = null; }

  const makeMesh = (arr, mat) => {
    if (arr.length === 0) return null;
    const geo = new THREE.BufferGeometry();
    geo.setAttribute('position', new THREE.BufferAttribute(arr, 3));
    // 色值 interleaved 在 arr 里: 每顶点6 float(pos3+color3)
    // BufferAttribute stride 是隐式的 —— 我们直接用非交错
    return null; // 占位, 实际走下面 build
  };

  // 非交错化: 把 [x,y,z,r,g,b]*n 拆成 position/color
  const buildGeo = (arr) => {
    if (arr.length === 0) return null;
    const vCount = arr.length / 6;
    const pos = new Float32Array(vCount * 3);
    const col = new Float32Array(vCount * 3);
    for (let i = 0; i < vCount; i++) {
      pos[i * 3] = arr[i * 6]; pos[i * 3 + 1] = arr[i * 6 + 1]; pos[i * 3 + 2] = arr[i * 6 + 2];
      col[i * 3] = arr[i * 6 + 3]; col[i * 3 + 1] = arr[i * 6 + 4]; col[i * 3 + 2] = arr[i * 6 + 5];
    }
    const geo = new THREE.BufferGeometry();
    geo.setAttribute('position', new THREE.BufferAttribute(pos, 3));
    geo.setAttribute('color', new THREE.BufferAttribute(col, 3));
    return geo;
  };

  const sGeo = buildGeo(data.solid);
  if (sGeo) {
    const mat = new THREE.MeshLambertMaterial({ vertexColors: true });
    const mesh = new THREE.Mesh(sGeo, mat);
    scene.add(mesh);
    chunk.mesh = mesh;
  }
  const wGeo = buildGeo(data.water);
  if (wGeo) {
    const mat = new THREE.MeshLambertMaterial({ vertexColors: true, transparent: true, opacity: 0.72, depthWrite: false });
    const mesh = new THREE.Mesh(wGeo, mat);
    scene.add(mesh);
    chunk.waterMesh = mesh;
  }
  chunk.dirty = false;
}

// ================= 昼夜循环 =================
function updateDayNight(dt) {
  dayTime = (dayTime + dt) % DAY_LENGTH;
  const t = dayTime / DAY_LENGTH;                       // 0..1
  const ang = t * Math.PI * 2 - Math.PI / 2;            // 0=日出
  const sunY = Math.sin(ang), sunX = Math.cos(ang);

  // 太阳/月亮位置(跟随玩家)
  const px = player.pos.x, pz = player.pos.z;
  sunSprite.position.set(px + sunX * 380, sunY * 380, pz + 120 * Math.cos(ang * 0.5));
  sunSprite.lookAt(camera.position);
  moonSprite.position.set(px - sunX * 380, -sunY * 380, pz - 120 * Math.cos(ang * 0.5));
  moonSprite.lookAt(camera.position);

  // 昼夜因子
  const dayFactor = Math.max(0, Math.min(1, sunY * 2 + 0.25));   // 日出日落渐变
  const nightFactor = 1 - dayFactor;

  sunLight.position.set(px + sunX * 100, Math.max(sunY, 0.05) * 100, pz + 40);
  sunLight.intensity = dayFactor * 1.05;
  moonLight.position.set(px - sunX * 100, Math.max(-sunY, 0.05) * 100, pz - 40);
  moonLight.intensity = nightFactor * 0.22;

  ambient.intensity = 0.18 + dayFactor * 0.30;
  hemiLight.intensity = 0.2 + dayFactor * 0.4;

  // 天空颜色渐变: 夜 -> 橙(晨昏) -> 蓝
  const dayTop = new THREE.Color(0x2a62c8), dayMid = new THREE.Color(0x9fc7ff), dayBot = new THREE.Color(0xd8e8ff);
  const duskTop = new THREE.Color(0x1a1a4e), duskMid = new THREE.Color(0xd97b3f), duskBot = new THREE.Color(0xf2a75c);
  const nightTop = new THREE.Color(0x050515), nightMid = new THREE.Color(0x0d0d26), nightBot = new THREE.Color(0x161630);
  const duskAmt = Math.max(0, 1 - Math.abs(sunY) * 5);   // 接近地平线
  const mix3 = (a, b, k) => a.clone().lerp(b, k);
  let top = mix3(nightTop, dayTop, dayFactor);
  let mid = mix3(nightMid, dayMid, dayFactor);
  let bot = mix3(nightBot, dayBot, dayFactor);
  top = mix3(top, duskTop, duskAmt * 0.6);
  mid = mix3(mid, duskMid, duskAmt * 0.7);
  bot = mix3(bot, duskBot, duskAmt * 0.7);
  const u = skyDome.material.uniforms;
  u.topColor.value.copy(top); u.midColor.value.copy(mid); u.botColor.value.copy(bot);

  // 雾色跟随中段天空
  scene.fog.color.copy(mid);
  stars.material.opacity = nightFactor * 0.9;
  clouds.material.opacity = 0.25 + dayFactor * 0.5;

  // 水下色调
  if (player.headInWater) {
    scene.fog.color.setHex(0x1a4a8a);
    scene.fog.near = 2; scene.fog.far = 24;
  } else {
    scene.fog.near = RENDER_DIST * CHUNK_SIZE * 0.55;
    scene.fog.far = RENDER_DIST * CHUNK_SIZE * 0.95;
  }
}

// ================= 输入 =================
function bindInput() {
  document.addEventListener('keydown', (e) => {
    if (e.repeat) return;
    keys[e.code] = true;
    if (!gameStarted) return;
    if (e.code === 'Escape') { togglePause(); return; }
    if (paused) return;
    if (e.code === 'F3') { e.preventDefault(); document.getElementById('debug').classList.toggle('hidden'); }
    if (e.code === 'F5') { e.preventDefault(); firstPerson = !firstPerson; }
    if (e.code.startsWith('Digit')) {
      const n = parseInt(e.code.slice(5));
      if (n >= 1 && n <= 9) inventory.select(n - 1);
    }
    if (e.code === 'Space') {
      const now = performance.now();
      if (now - player.lastSpaceTime < 280) {
        player.flying = !player.flying;
        player.vel.y = 0;
        showToast(player.flying ? '飞行模式: 开' : '飞行模式: 关');
      }
      player.lastSpaceTime = now;
    }
  });
  document.addEventListener('keyup', (e) => { keys[e.code] = false; });

  // 指针锁定
  canvas.addEventListener('mousedown', (e) => {
    if (!gameStarted || paused) return;
    if (document.pointerLockElement !== canvas) { canvas.requestPointerLock(); return; }
    if (e.button === 0) startBreak();
    if (e.button === 2) placeBlock();
    if (e.button === 1) {
      e.preventDefault();
      // 中键取色
      if (currentHit) {
        const id = world.getBlock(currentHit.x, currentHit.y, currentHit.z);
        if (id) { inventory.setSlot(inventory.selected, id); SFX.pop(); }
      }
    }
  });
  document.addEventListener('mouseup', (e) => { if (e.button === 0) stopBreak(); });
  document.addEventListener('contextmenu', (e) => e.preventDefault());
  document.addEventListener('mousemove', (e) => {
    if (document.pointerLockElement !== canvas || paused) return;
    const s = 0.0024;
    player.yaw -= e.movementX * s;
    player.pitch -= e.movementY * s;
    player.pitch = Math.max(-Math.PI / 2 + 0.01, Math.min(Math.PI / 2 - 0.01, player.pitch));
  });
  document.addEventListener('wheel', (e) => {
    if (!gameStarted || paused) return;
    inventory.scroll(e.deltaY > 0 ? 1 : -1);
  }, { passive: true });

  document.addEventListener('pointerlockchange', () => {
    if (gameStarted && document.pointerLockElement !== canvas && !paused) {
      togglePause(true);
    }
  });
}

function readInput() {
  input.forward = !!(keys['KeyW'] || keys['ArrowUp']);
  input.back = !!(keys['KeyS'] || keys['ArrowDown']);
  input.left = !!(keys['KeyA'] || keys['ArrowLeft']);
  input.right = !!(keys['KeyD'] || keys['ArrowRight']);
  input.jump = !!keys['Space'];
  input.sprint = !!(keys['ControlLeft'] || keys['ControlRight'] || keys['KeyR']);
  input.sneak = !!(keys['ShiftLeft'] || keys['ShiftRight']);
}

// ================= 破坏/放置 =================
function startBreak() {
  if (!currentHit) return;
  const id = world.getBlock(currentHit.x, currentHit.y, currentHit.z);
  if (!id || id === B.BEDROCK) return;
  const def = BLOCKS[id];
  const hard = (def && def.hard) || 1;
  breakState = { x: currentHit.x, y: currentHit.y, z: currentHit.z, progress: 0, need: Math.min(hard, 1.2) * 0.55, id };
  document.getElementById('break-progress').classList.add('active');
}

function stopBreak() {
  breakState = null;
  document.getElementById('break-progress').classList.remove('active');
  document.getElementById('break-bar').style.width = '0%';
}

function updateBreak(dt) {
  if (!breakState) return;
  if (!currentHit || currentHit.x !== breakState.x || currentHit.y !== breakState.y || currentHit.z !== breakState.z) {
    stopBreak(); return;
  }
  breakState.progress += dt;
  const pct = Math.min(1, breakState.progress / breakState.need);
  document.getElementById('break-bar').style.width = (pct * 100) + '%';
  // 挖掘音效(节奏)
  if (Math.floor(breakState.progress * 6) !== Math.floor((breakState.progress - dt) * 6)) {
    SFX.dig(breakState.id);
  }
  if (pct >= 1) {
    const dropId = blockDrop(breakState.id);
    world.setBlock(breakState.x, breakState.y, breakState.z, B.AIR);
    particles.spawnBlockBreak(breakState.x, breakState.y, breakState.z, breakState.id);
    SFX.breakBlock(breakState.id);
    // 掉落物直接进背包(简化生存): 找空位或当前格放掉落
    if (dropId !== B.AIR && !inventory.slots.includes(dropId)) {
      // 替换当前选择格(若当前格为空类) — 创造模式保持简洁: 不自动放
    }
    stopBreak();
  }
}

function placeBlock() {
  if (!currentHit) return;
  const { x, y, z, nx, ny, nz } = currentHit;
  const tx = x + nx, ty = y + ny, tz = z + nz;
  if (ty < 0 || ty >= CHUNK_HEIGHT) return;
  const cur = world.getBlock(tx, ty, tz);
  if (cur !== B.AIR && !(BLOCKS[cur] && BLOCKS[cur].liquid)) return;
  // 不能放在自己身上
  const id = inventory.current();
  const w = PLAYER_W / 2;
  const pCollide = tx + 1 > player.pos.x - w && tx < player.pos.x + w &&
                   tz + 1 > player.pos.z - w && tz < player.pos.z + w &&
                   ty + 1 > player.pos.y && ty < player.pos.y + PLAYER_H;
  if (pCollide && isSolid(id)) { showToast('不能放在自己身上'); return; }
  if (world.setBlock(tx, ty, tz, id)) {
    SFX.place(id);
  }
}

// ================= HUD =================
let toastTimer = null;
function showToast(msg) {
  const el = document.getElementById('toast');
  el.textContent = msg;
  el.classList.add('show');
  clearTimeout(toastTimer);
  toastTimer = setTimeout(() => el.classList.remove('show'), 1600);
}

function updateDebug() {
  const dbg = document.getElementById('debug');
  if (dbg.classList.contains('hidden')) return;
  const p = player.pos;
  const h = world.gen.heightAt(Math.floor(p.x), Math.floor(p.z));
  const biomeNames = ['平原', '沙漠', '雪原', '山地'];
  const biome = world.gen.biomeAt(Math.floor(p.x), Math.floor(p.z));
  const t = (dayTime / DAY_LENGTH * 24 + 6) % 24;
  const hh = String(Math.floor(t)).padStart(2, '0');
  const mm = String(Math.floor((t % 1) * 60)).padStart(2, '0');
  dbg.textContent =
    `WovraCraft  ${stats.fps} fps\n` +
    `XYZ: ${p.x.toFixed(1)} / ${p.y.toFixed(1)} / ${p.z.toFixed(1)}\n` +
    `区块: ${Math.floor(p.x / 16)}, ${Math.floor(p.z / 16)}  已加载: ${world.chunks.size}\n` +
    `群系: ${biomeNames[biome]}  地表: ${h}\n` +
    `时间: ${hh}:${mm}  ${player.inWater ? '(水中)' : ''}${player.flying ? '(飞行)' : ''}\n` +
    `手持: ${blockName(inventory.current())}`;
}

// ================= 暂停/存档 =================
function togglePause(forcePause) {
  if (!gameStarted) return;
  paused = forcePause === true ? true : !paused;
  document.getElementById('pause-menu').classList.toggle('hidden', !paused);
  if (paused) {
    document.exitPointerLock && document.exitPointerLock();
    SaveManager.save(game);
  } else {
    canvas.requestPointerLock();
  }
}

// ================= 游戏对象 =================
const game = {
  world: null, player: null, inventory: null,
  get dayTime() { return dayTime; },
  set dayTime(v) { dayTime = v; },
};

function startGame(seedStr, fromSave) {
  const save = fromSave ? SaveManager.load() : null;
  if (save) seedStr = save.seed;

  world = new World(seedStr);
  game.world = world;
  player = new Player(world);
  game.player = player;

  if (save) {
    player.pos = save.player.pos;
    player.yaw = save.player.yaw;
    player.pitch = save.player.pitch;
    player.flying = !!save.player.flying;
    dayTime = save.dayTime;
    for (const [k, v] of save.edits) world.edits.set(k, v);
  } else {
    const sp = world.findSpawn();
    player.pos = sp;
  }

  // 预生成玩家周围区块, 防止落地掉空
  const pcx = Math.floor(player.pos.x / CHUNK_SIZE);
  const pcz = Math.floor(player.pos.z / CHUNK_SIZE);
  for (let dz = -2; dz <= 2; dz++)
    for (let dx = -2; dx <= 2; dx++)
      world.ensureChunk(pcx + dx, pcz + dz);
  if (!save) {
    // 贴地
    let y = CHUNK_HEIGHT - 1;
    while (y > 1 && !isSolid(world.getBlock(Math.floor(player.pos.x), y, Math.floor(player.pos.z)))) y--;
    player.pos.y = y + 1.05;
  }

  inventory = new Inventory(document.getElementById('hotbar'));
  if (save && save.hotbar) { inventory.slots = save.hotbar; inventory.render(); }
  game.inventory = inventory;

  particles = new ParticleSystem(scene);

  document.getElementById('menu').classList.add('hidden');
  gameStarted = true;
  paused = false;
  canvas.requestPointerLock();
  SFX.init();
  showToast(save ? '欢迎回来!' : '欢迎来到 WovraCraft!');
}

// ================= 主循环 =================
let lastT = performance.now();
function loop() {
  requestAnimationFrame(loop);
  const now = performance.now();
  let dt = (now - lastT) / 1000;
  lastT = now;
  if (dt > 0.1) dt = 0.1;

  // FPS 统计
  stats.frames++; stats.ft += dt;
  if (stats.ft >= 1) { stats.fps = stats.frames; stats.frames = 0; stats.ft = 0; }

  if (gameStarted && !paused) {
    readInput();
    const stepEvt = player.update(dt, input);
    if (stepEvt === 'step') {
      const under = world.getBlock(Math.floor(player.pos.x), Math.floor(player.pos.y - 0.1), Math.floor(player.pos.z));
      SFX.step(under);
    }

    // 相机
    const bobY = player.onGround ? Math.sin(player.bobPhase) * 0.05 : 0;
    const bobX = player.onGround ? Math.cos(player.bobPhase * 0.5) * 0.025 : 0;
    const eye = { x: player.pos.x, y: player.pos.y + EYE_HEIGHT + bobY, z: player.pos.z };
    if (firstPerson) {
      camera.position.set(eye.x, eye.y, eye.z);
    } else {
      // 第三人称
      const back = 4;
      const dx = -Math.sin(player.yaw) * Math.cos(player.pitch) * -back;
      const dy = Math.sin(player.pitch) * -back;
      const dz = -Math.cos(player.yaw) * Math.cos(player.pitch) * -back;
      camera.position.set(eye.x + dx, eye.y - dy + 1.2, eye.z + dz);
    }
    camera.rotation.set(0, 0, 0);
    camera.rotateY(player.yaw + Math.PI);
    camera.rotateX(-player.pitch);
    // (约定: yaw=0 面向 -Z, 与 raycast 一致)

    // 瞄准
    const dir = new THREE.Vector3(0, 0, -1).applyQuaternion(camera.quaternion);
    currentHit = raycastVoxel(world, eye.x, eye.y, eye.z, dir.x, dir.y, dir.z, REACH);
    if (currentHit.hit) {
      highlightMesh.visible = true;
      highlightMesh.position.set(currentHit.x + 0.5, currentHit.y + 0.5, currentHit.z + 0.5);
    } else {
      highlightMesh.visible = false;
      if (breakState) stopBreak();
    }

    updateBreak(dt);
    particles.update(dt);
    updateChunks();
    updateDayNight(dt);
    updateDebug();

    clouds.position.x = player.pos.x;
    clouds.position.z = player.pos.z;
    clouds.material.map.offset.x += dt * 0.0015;

    skyDome.position.set(player.pos.x, 0, player.pos.z);
    stars.position.set(player.pos.x, 0, player.pos.z);
  }

  renderer.render(scene, camera);
}

// ================= 菜单绑定 =================
function bindMenu() {
  const btnPlay = document.getElementById('btn-play');
  const btnContinue = document.getElementById('btn-continue');
  const seedInput = document.getElementById('seed-input');

  if (SaveManager.hasSave()) btnContinue.classList.remove('hidden');

  btnPlay.addEventListener('click', () => {
    const s = seedInput.value.trim() || String(Math.floor(Math.random() * 9999999));
    if (SaveManager.hasSave()) SaveManager.clear();  // 新开局覆盖旧档
    startGame(s, false);
  });
  btnContinue.addEventListener('click', () => startGame(null, true));

  document.getElementById('btn-resume').addEventListener('click', () => togglePause());
  document.getElementById('btn-save').addEventListener('click', () => {
    showToast(SaveManager.save(game) ? '世界已保存' : '保存失败');
  });
  document.getElementById('btn-quit').addEventListener('click', () => {
    SaveManager.save(game);
    location.reload();
  });
}

// ================= 启动 =================
initRenderer();
bindInput();
bindMenu();
loop();
","path":"js/main.js"}

{"content":"/* 冒烟测试: 在 Node 中验证核心逻辑(无 DOM/THREE 依赖的模块) */
'use strict';
const fs = require('fs');
const path = require('path');

// 加载非 DOM 模块
const load = (f) => new Function(fs.readFileSync(path.join(__dirname, '..', 'js', f), 'utf8'))();
global.window = {};
load('constants.js');
load('noise.js');
load('worldgen.js');
load('chunks.js');
load('mesher.js');
load('physics.js');
load('raycast.js');

let pass = 0, fail = 0;
function ok(cond, msg) {
  if (cond) { pass++; console.log('  ✓', msg); }
  else { fail++; console.error('  ✗', msg); }
}

console.log('== 噪声 ==');
{
  const p1 = new Perlin(123), p2 = new Perlin(123);
  ok(p1.noise2(1.5, 2.5) === p2.noise2(1.5, 2.5), '同种子确定性');
  ok(Math.abs(p1.noise2(0.3, 0.7)) <= 1.01, '输出范围 [-1,1]');
  ok(p1.noise2(0.3, 0.7) !== p1.noise2(0.9, 0.1), '不同输入不同输出');
  let mn = 1e9, mx = -1e9;
  for (let i = 0; i < 2000; i++) {
    const v = p1.fbm2(i * 0.05, i * 0.031, 4);
    mn = Math.min(mn, v); mx = Math.max(mx, v);
  }
  ok(mx - mn > 0.5, `fbm 有足够波动 (range=${(mx - mn).toFixed(2)})`);
}

console.log('== 世界生成 ==');
{
  const g = new WorldGen('404');
  const h1 = g.heightAt(10, 10), h2 = g.heightAt(10, 10);
  ok(h1 === h2, '高度确定性');
  ok(h1 >= 3 && h1 < CHUNK_HEIGHT, `高度在界内 (${h1})`);
  ok(typeof g.biomeAt(0, 0) === 'number' && g.biomeAt(0, 0) >= 0 && g.biomeAt(0, 0) <= 3, '群系枚举合法');
  // 采样多坐标确保多样
  const hs = new Set();
  for (let i = 0; i < 30; i++) hs.add(g.heightAt(i * 37, i * 23));
  ok(hs.size > 5, `地形有多样性 (${hs.size} 种高度)`);
}

console.log('== 区块与世界 ==');
{
  const w = new World('404');
  const c = w.ensureChunk(0, 0);
  ok(c.generated, '区块生成');
  let nonAir = 0;
  for (let i = 0; i < c.blocks.length; i++) if (c.blocks[i]) nonAir++;
  ok(nonAir > 1000, `区块非空 (${nonAir} 方块)`);
  ok(c.get(0, 0, 0) === B.BEDROCK, '底层基岩');
  // 世界坐标 get/set
  const b1 = w.getBlock(5, 30, 5);
  w.setBlock(5, 30, 5, B.BRICK);
  ok(w.getBlock(5, 30, 5) === B.BRICK, 'setBlock/getBlock 生效');
  ok(w.edits.has('5,30,5'), '修改记录进 edits');
  w.setBlock(5, 30, 5, b1);
  // 树: 搜索多区块找至少一棵
  let trees = 0;
  for (let cz = -3; cz <= 3; cz++) for (let cx = -3; cx <= 3; cx++) {
    const ch = w.ensureChunk(cx, cz);
    for (let i = 0; i < ch.blocks.length; i++) if (ch.blocks[i] === B.LOG) trees++;
  }
  ok(trees > 0, `存在树木(原木数=${trees})`);
  // 水存在
  let waters = 0, ores = 0, caves = 0;
  for (const [, ch] of w.chunks) {
    for (let i = 0; i < ch.blocks.length; i++) {
      const id = ch.blocks[i];
      if (id === B.WATER) waters++;
      if (id === B.COAL_ORE || id === B.IRON_ORE) ores++;
      if (id === B.AIR) caves++;
    }
  }
  ok(waters > 0, '存在水');
  ok(ores > 0, `存在矿石(${ores})`);
  ok(caves > 0, '存在洞穴/空气');
}

console.log('== 网格化 ==');
{
  const w = new World('404');
  const c = w.ensureChunk(0, 0);
  const data = meshChunk(w, c);
  ok(data.solid.length > 0, `实体网格有顶点 (${data.solid.length / 6} 顶点)`);
  ok(data.solid.length % 36 === 0, '顶点数是 6 的倍数(quad x2 tri)');
  // 数值合法
  let bad = 0;
  for (let i = 0; i < data.solid.length; i++) if (!isFinite(data.solid[i]) || Math.abs(data.solid[i]) > 1000) bad++;
  ok(bad === 0, '顶点数值合法');
}

console.log('== 物理 ==');
{
  const w = new World('404');
  const p = new Player(w);
  const sp = w.findSpawn();
  p.pos = { ...sp };
  // 让他落到地面
  for (let i = 0; i < 200; i++) p.update(1 / 60, { forward: false, back: false, left: false, right: false, jump: false, sprint: false, sneak: false });
  const groundY = w.gen.heightAt(Math.floor(p.pos.x), Math.floor(p.pos.z));
  ok(p.onGround, '落到地面');
  ok(Math.abs(p.pos.y - (groundY + 1)) < 2.5, `站在地表附近 (y=${p.pos.y.toFixed(1)}, 地表=${groundY})`);
  // 行走
  const x0 = p.pos.x;
  for (let i = 0; i < 60; i++) p.update(1 / 60, { forward: true, back: false, left: false, right: false, jump: false, sprint: false, sneak: false });
  const moved = Math.hypot(p.pos.x - x0, p.pos.z);
  ok(moved > 2, `行走移动 (${moved.toFixed(1)}m/s)`);
  // 跳跃
  const p2 = new Player(w);
  p2.pos = { ...sp };
  for (let i = 0; i < 200; i++) p2.update(1 / 60, { forward: false, back: false, left: false, right: false, jump: false, sprint: false, sneak: false });
  const yBefore = p2.pos.y;
  p2.update(1 / 60, { forward: false, back: false, left: false, right: false, jump: true, sprint: false, sneak: false });
  for (let i = 0; i < 30; i++) p2.update(1 / 60, { forward: false, back: false, left: false, right: false, jump: false, sprint: false, sneak: false });
  ok(p2.pos.y > yBefore + 0.3, `跳跃升高 (${(p2.pos.y - yBefore).toFixed(2)}m 峰值轨迹中)`);
}

console.log('== 射线 ==');
{
  const w = new World('404');
  w.ensureChunk(0, 0);
  const h = w.gen.heightAt(8, 8);
  // 从地表上方往下射
  const r = raycastVoxel(w, 8.5, h + 3, 8.5, 0, -1, 0, 10);
  ok(r.hit, '垂直向下命中');
  ok(r.y === h, `命中地表方块 y=${r.y} (期望 ${h})`);
  ok(r.ny === 1, '法线朝上(放置面)');
  // 朝天空射
  const r2 = raycastVoxel(w, 8.5, h + 3, 8.5, 0, 1, 0, 10);
  ok(!r2.hit, '朝天空不命中');
}

console.log(`\n结果: ${pass} 通过, ${fail} 失败`);
process.exit(fail > 0 ? 1 : 0);
