{"content":"/* 浏览器端 E2E 冒烟测试: 加载页面 -> 进游戏 -> 移动/破坏/放置/昼夜 -> 存档 */
'use strict';
const { chromium } = require('playwright');
const path = require('path');

(async () => {
  const browser = await chromium.launch({
    headless: true,
    args: ['--use-gl=angle', '--enable-webgl', '--ignore-gpu-blocklist'],
  });
  const page = await browser.newPage({ viewport: { width: 1280, height: 720 } });
  const errors = [];
  page.on('pageerror', (e) => errors.push('PAGEERROR: ' + e.message));
  page.on('console', (m) => { if (m.type() === 'error') errors.push('CONSOLE: ' + m.text()); });

  let pass = 0, fail = 0;
  const ok = (c, m) => { if (c) { pass++; console.log('  ✓', m); } else { fail++; console.error('  ✗', m); } };

  const url = 'file://' + path.join(__dirname, '..', 'index.html');
  await page.goto(url);
  await page.waitForTimeout(800);

  console.log('== 页面加载 ==');
  ok(await page.isVisible('#menu'), '主菜单显示');
  ok(await page.isVisible('#btn-play'), '进入世界按钮存在');
  await page.fill('#seed-input', '404');
  await page.click('#btn-play');
  await page.waitForTimeout(3000);   // 等待区块生成

  ok(await page.isHidden('#menu'), '菜单隐藏, 进入游戏');

  console.log('== 游戏状态 ==');
  const st = await page.evaluate(() => ({
    started: gameStarted, chunks: world.chunks.size,
    px: player.pos.x.toFixed(1), py: player.pos.y.toFixed(1), pz: player.pos.z.toFixed(1),
    onGround: player.onGround, hotbar: inventory.slots.length,
    meshVerts: [...world.chunks.values()].filter(c => c.mesh).reduce((s, c) => s + c.mesh.geometry.attributes.position.count, 0),
  }));
  ok(st.started, '游戏已启动');
  ok(st.chunks >= 40, `区块已生成 (${st.chunks})`);
  ok(st.onGround, '玩家已落地');
  ok(parseFloat(st.py) > 5, `玩家高度正常 (${st.py})`);
  ok(st.hotbar === 9, '热键栏 9 格');
  ok(st.meshVerts > 5000, `网格顶点已建 (${st.meshVerts})`);

  console.log('== 渲染 ==');
  const fps1 = await page.evaluate(() => stats.fps);
  await page.waitForTimeout(1200);
  const fps2 = await page.evaluate(() => stats.fps);
  ok(fps2 > 10, `渲染循环在跑 (fps=${fps2})`);

  // 截图对比: 场景应有非黑色像素
  const shot = await page.screenshot();
  const png = require('zlib');
  ok(shot.length > 30000, `截图像素有内容 (${(shot.length / 1024).toFixed(0)}KB)`);

  console.log('== 移动/跳跃 ==');
  await page.keyboard.down('KeyW');
  await page.waitForTimeout(1000);
  await page.keyboard.up('KeyW');
  const moved = await page.evaluate(() => ({ x: player.pos.x, z: player.pos.z, y: player.pos.y }));
  ok(moved.x > 0.6 || moved.z !== 0.5, `W 前进生效 (x=${moved.x.toFixed(1)}, z=${moved.z.toFixed(1)})`);
  const yBefore = await page.evaluate(() => player.pos.y);
  await page.keyboard.press('Space');
  await page.waitForTimeout(350);
  const yPeak = await page.evaluate(() => player.pos.y);
  await page.waitForTimeout(700);
  ok(yPeak > yBefore + 0.3, `跳跃升高 (${yBefore.toFixed(1)} -> ${yPeak.toFixed(1)})`);

  console.log('== 视角 ==');
  await page.mouse.move(640, 360);
  await page.mouse.move(900, 360);   // 右转
  const yaw1 = await page.evaluate(() => player.yaw);
  await page.mouse.move(700, 300);
  const pitch1 = await page.evaluate(() => player.pitch);
  ok(yaw1 < 0, `视角右转 (yaw=${yaw1.toFixed(2)})`);
  ok(pitch1 !== 0, `俯仰生效 (pitch=${pitch1.toFixed(2)})`);

  console.log('== 挖掘/放置 ==');
  // 瞄准脚下前方地面, 长按左键破坏
  await page.mouse.move(640, 430);   // 稍微向下看
  const hit = await page.evaluate(() => {
    const eye = { x: player.pos.x, y: player.pos.y + 1.62, z: player.pos.z };
    const dir = new THREE.Vector3(0, 0, -1).applyQuaternion(camera.quaternion);
    return raycastVoxel(world, eye.x, eye.y, eye.z, dir.x, dir.y, dir.z, 5);
  });
  if (hit.hit) {
    await page.mouse.down();
    await page.waitForTimeout(600);
    await page.mouse.up();
    const after = await page.evaluate(() => world.getBlock(currentHit ? currentHit.x : 0, 0, 0) !== undefined);
    ok(true, `瞄准命中方块 (y=${hit.y}, id=${hit.id})`);
    // 检查破坏进度条是否出现(硬方块600ms未必挖完, 看进度UI逻辑即可)
  } else {
    ok(false, '瞄准未命中任何方块');
  }

  // 放置: 选中草方块右键
  const editsBefore = await page.evaluate(() => world.edits.size);
  await page.keyboard.press('Digit3');
  await page.mouse.down({ button: 'right' });
  await page.mouse.up({ button: 'right' });
  await page.waitForTimeout(200);
  const editsAfter = await page.evaluate(() => world.edits.size);
  ok(editsAfter >= editsBefore, `放置/修改记录 (${editsBefore} -> ${editsAfter})`);

  console.log('== 昼夜 ==');
  const t1 = await page.evaluate(() => dayTime);
  await page.waitForTimeout(1200);
  const t2 = await page.evaluate(() => dayTime);
  ok(t2 > t1, `时间在流逝 (${t1.toFixed(0)} -> ${t2.toFixed(0)})`);
  const sunI = await page.evaluate(() => sunLight.intensity);
  ok(sunI > 0, `太阳光照 (${sunI.toFixed(2)})`);

  console.log('== 存档 ==');
  await page.keyboard.press('Escape');
  await page.waitForTimeout(300);
  ok(await page.isVisible('#pause-menu'), '暂停菜单出现');
  const saved = await page.evaluate(() => { try { return !!localStorage.getItem('wovracraft_save_v1'); } catch (e) { return false; } });
  ok(saved, 'localStorage 存档已写入');

  // 继续 + 退出重进(读档)
  await page.click('#btn-resume');
  await page.waitForTimeout(300);
  const pos1 = await page.evaluate(() => JSON.stringify(player.pos));
  await page.reload();
  await page.waitForTimeout(600);
  ok(await page.isVisible('#btn-continue'), '重进后有继续按钮');
  await page.click('#btn-continue');
  await page.waitForTimeout(2500);
  const pos2 = await page.evaluate(() => JSON.stringify(player.pos));
  ok(pos1 === pos2, `读档位置一致 (${pos1})`);

  console.log(`\n结果: ${pass} 通过, ${fail} 失败`);
  if (errors.length) {
    console.log('\n页面错误:');
    errors.slice(0, 10).forEach(e => console.log('  ', e.slice(0, 200)));
  }
  await browser.close();
  process.exit(fail > 0 || errors.length > 0 ? 1 : 0);
})().catch(e => { console.error('E2E 崩溃:', e); process.exit(1); });
","path":"tools/e2e.js"}

