{"content":"/* 调试: 相机朝向约定标定 */
'use strict';
const { chromium } = require('playwright');
const path = require('path');

(async () => {
  const browser = await chromium.launch({ headless: true, args: ['--use-gl=angle', '--enable-webgl'] });
  const page = await browser.newPage({ viewport: { width: 1280, height: 720 } });
  page.on('pageerror', e => console.log('PAGEERROR:', e.message));
  await page.goto('file://' + path.join(__dirname, '..', 'index.html'));
  await page.waitForTimeout(500);
  await page.fill('#seed-input', '404');
  await page.click('#btn-play');
  await page.waitForTimeout(2000);

  const probe = await page.evaluate(async () => {
    const out = [];
    for (const p of [0.5, 0, -0.5]) {
      for (const yw of [0, Math.PI / 2]) {
        player.pitch = p; player.yaw = yw;
        // 等一帧让 loop 应用相机
        await new Promise(r => requestAnimationFrame(r));
        const dir = new THREE.Vector3(0, 0, -1).applyQuaternion(camera.quaternion);
        out.push({ pitch: p, yaw: yw.toFixed(2), dir: [dir.x.toFixed(2), dir.y.toFixed(2), dir.z.toFixed(2)] });
      }
    }
    return out;
  });
  for (const o of probe) console.log(`pitch=${o.pitch} yaw=${o.yaw} dir=(${o.dir})`);
  await browser.close();
})();
","path":"tools/debug-cam.js"}

