'use strict';
const fs = require('fs');
const path = require('path');
const vm = require('vm');
const load = (f) => vm.runInThisContext(fs.readFileSync(path.join(__dirname, '..', 'js', f), 'utf8'), { filename: f });
global.window = {};
load('constants.js'); load('noise.js'); load('worldgen.js'); load('chunks.js'); load('raycast.js');

// 实测相机约定: pitch>0 时 dir.y<0
// pickBlock 中 dx = -sin(yaw)*cos(pitch); dz = -cos(yaw)*cos(pitch)
// 在 yaw=0 时: dz=-cos(pitch) => dir.z<0, 但实测 dir.z=+0.88 → pickBlock 与相机 Z 反了
const pitch = 0.5, yaw = 0;
const dx = -Math.sin(yaw) * Math.cos(pitch);
const dy = Math.sin(pitch);
const dz = -Math.cos(yaw) * Math.cos(pitch);
console.log(`pickBlock 约定: yaw=${yaw}, pitch=${pitch} => dir=(${dx.toFixed(2)}, ${dy.toFixed(2)}, ${dz.toFixed(2)})`);
console.log('相机实测      : dir=(-0.00, -0.48, 0.88)');
console.log('dy 符号:', dy > 0 ? 'pickBlock 抬头向上, 相机低头向下 → dy 也反了' : '一致');
