function placeBlock() {
  if (!currentHit) return;
  const { x, y, z, nx, ny, nz } = currentHit;
  const tx = x + nx, ty = y + ny, tz = z + nz;
  if (ty < 0 || ty >= CHUNK_HEIGHT) return;
  const cur = world.getBlock(tx, ty, tz);
  if (cur !== B.AIR && !(BLOCKS[cur] && BLOCKS[cur].liquid)) return;
  // 不能放在自己身上
  const id = inventory.current();
  const w = PLAYER_W / 2;
  const pCollide = tx + 1 > player.pos.x - w && tx < player.pos.x + w &&
                   tz + 1 > player.pos.z - w && tz < player.pos.z + w &&
                   ty + 1 > player.pos.y && ty < player.pos.y + PLAYER_H;
  if (pCollide && isSolid(id)) { showToast('不能放在自己身上'); return; }
  if (world.setBlock(tx, ty, tz, id)) {
    SFX.place(id);
  }
}

