{"content":"/* 调试: 复刻到放置断言, 揭示 mouse.down 时 pointerLock/事件流状态 */
'use strict';
const { chromium } = require('playwright');
const path = require('path');

(async () => {
  const browser = await chromium.launch({ headless: true, args: ['--use-gl=angle', '--enable-webgl'] });
  const page = await browser.newPage({ viewport: { width: 1280, height: 720 } });
  page.on('pageerror', e => console.log('PAGEERROR:', e.message));
  await page.goto('file://' + path.join(__dirname, '..', 'index.html'));
  await page.waitForTimeout(500);
  await page.fill('#seed-input', '404');
  await page.click('#btn-play');
  await page.waitForTimeout(2000);
  // 完整复刻: 左键一次(锁定) + W + Space
  await page.mouse.move(640, 360);
  await page.mouse.down(); await page.waitForTimeout(100); await page.mouse.up();
  await page.keyboard.down('KeyW'); await page.waitForTimeout(1000); await page.keyboard.up('KeyW');
  await page.keyboard.down('Space'); await page.waitForTimeout(150); await page.keyboard.up('Space');
  await page.waitForTimeout(250);
  await page.mouse.click(640, 360);
  await page.waitForTimeout(300);

  // hook placeBlock 计数
  await page.evaluate(() => {
    window.__calls = [];
    const orig = placeBlock;
    window.placeBlock = function () { window.__calls.push(currentHit ? { ...currentHit } : null); return orig(); };
  });

  // e2e 放置段
  await page.evaluate(() => { player.pitch = 0.9; player.yaw = 0; player.vel = { x: 0, y: 0, z: 0 }; });
  await page.waitForTimeout(250);
  await page.evaluate(async () => {
    startBreak();
    for (let i = 0; i < 100 && breakState; i++) { updateBreak(1 / 30); await new Promise(r => setTimeout(r, 5)); }
  });
  await page.evaluate(async () => {
    player.pitch = 0.9; player.yaw = 0; player.vel = { x: 0, y: 0, z: 0 };
    for (let i = 0; i < 6; i++) await new Promise(r => requestAnimationFrame(r));
    if (currentHit) {
      const tx = currentHit.x + currentHit.nx, ty = currentHit.y + currentHit.ny, tz = currentHit.z + currentHit.nz;
      if (isSolid(world.getBlock(tx, ty, tz))) world.setBlock(tx, ty, tz, B.AIR, false);
    }
    for (let i = 0; i < 3; i++) await new Promise(r => requestAnimationFrame(r));
  });
  await page.mouse.down({ button: 'right' });
  await page.waitForTimeout(60);
  await page.mouse.up({ button: 'right' });
  await page.waitForTimeout(200);

  const res = await page.evaluate(() => ({
    calls: window.__calls,
    lock: document.pointerLockElement === document.getElementById('game-canvas'),
    edits: world.edits.size,
    paused,
  }));
  console.log(JSON.stringify(res, null, 2));
  await browser.close();
})();
