'use strict';
const { chromium } = require('playwright');
const path = require('path');

(async () => {
  const browser = await chromium.launch({ headless: true, args: ['--use-gl=angle', '--enable-webgl'] });
  const page = await browser.newPage({ viewport: { width: 1280, height: 720 } });
  page.on('pageerror', e => console.log('PAGEERROR:', e.message));
  await page.goto('file://' + path.join(__dirname, '..', 'index.html'));
  await page.waitForTimeout(500);
  await page.fill('#seed-input', '404');
  await page.click('#btn-play');
  await page.waitForTimeout(2000);
  await page.mouse.move(640, 360);
  await page.mouse.down(); await page.waitForTimeout(100); await page.mouse.up();
  await page.keyboard.down('KeyW'); await page.waitForTimeout(1000); await page.keyboard.up('KeyW');
  await page.keyboard.down('Space'); await page.waitForTimeout(150); await page.keyboard.up('Space');
  await page.waitForTimeout(250);
  await page.mouse.click(640, 360);
  await page.waitForTimeout(300);

  const probe = await page.evaluate(async () => {
    player.pitch = 0.9; player.yaw = 0; player.vel = { x: 0, y: 0, z: 0 };
    for (let i = 0; i < 6; i++) await new Promise(r => requestAnimationFrame(r));
    const log = { hitBeforeClear: currentHit ? { ...currentHit } : null };
    if (currentHit) {
      const tx = currentHit.x + currentHit.nx, ty = currentHit.y + currentHit.ny, tz = currentHit.z + currentHit.nz;
      log.clearing = `${tx},${ty},${tz}`;
      log.wasSolid = isSolid(world.getBlock(tx, ty, tz));
      if (log.wasSolid) world.setBlock(tx, ty, tz, B.AIR, false);
      log.nowEmpty = world.getBlock(tx, ty, tz);
    }
    for (let i = 0; i < 3; i++) await new Promise(r => requestAnimationFrame(r));
    log.hitAfterClear = currentHit ? { ...currentHit } : null;
    // 注意: setBlock(B.AIR) 会 markDirty 命中区块, 3帧够网格重建吗? 无所谓, currentHit 走 getBlock
    // 但 currentHit 是主循环 raycast 更新的 — 挖空目标后, 射线会飞过空位命中更远处!
    if (log.hitAfterClear) {
      const t = { tx: log.hitAfterClear.x + log.hitAfterClear.nx, ty: log.hitAfterClear.y + log.hitAfterClear.ny, tz: log.hitAfterClear.z + log.hitAfterClear.nz };
      log.newTarget = t;
      log.newTargetVoxel = world.getBlock(t.tx, t.ty, t.tz);
    }
    return log;
  });
  console.log(JSON.stringify(probe, null, 2));
  await browser.close();
})();
